<template>
  <div class="office-page"><AppSidebar/><main class="main"><header class="head"><div><h2>{{z.org}}</h2><p>{{z.desc}}</p></div><div class="metrics"><el-tag type="danger">{{z.head}} 1</el-tag><el-tag type="primary">{{z.groups}} {{org.groups.length}}</el-tag><el-tag type="success">{{z.members}} {{org.members.length}}</el-tag></div></header>
    <div class="top-grid"><section class="panel old-chart"><div class="panel-head"><b>{{z.relation}}</b><span>{{z.whole}}</span></div><div class="dept"><b>{{org.department?org.department.name:z.dept}}</b><small>{{z.head}} · {{z.wang}}</small></div><div class="vline"></div><div class="group-row"><div v-for="(g,i) in org.groups" :key="g.id" class="group-slot"><div class="branch"></div><div class="group-card" :class="'color'+i"><b>{{g.name}}</b><small>{{memberName(g.leader_user_id)||z.unset}} · {{groupMembers(g.id).length}} {{z.people}}</small></div><div class="names"><span v-for="m in groupMembers(g.id).filter(x=>x.role==='member')" :key="m.id">{{m.display_name}}</span></div></div></div></section><section class="panel"><div class="panel-head"><b>{{z.memberList}}</b><span>{{z.readOnly}}</span></div><el-table :data="org.members" size="mini" stripe><el-table-column prop="display_name" :label="z.member" width="110"/><el-table-column :label="z.role" width="105"><template slot-scope="{row}"><el-tag size="mini" :type="roleType(row.role)">{{roleName(row.role)}}</el-tag></template></el-table-column><el-table-column :label="z.group"><template slot-scope="{row}">{{groupName(row.group_id)||z.direct}}</template></el-table-column><el-table-column :label="z.manager"><template slot-scope="{row}">{{memberName(row.manager_user_id)||'-'}}</template></el-table-column></el-table></section></div>
    <section class="panel task-tree"><div class="panel-head"><div><b>{{z.teamTasks}}</b><span>{{z.taskDesc}}</span></div><div class="legend"><i class="done"></i>{{z.done}}<i class="doing"></i>{{z.doing}}<i class="todo"></i>{{z.todo}}</div></div><div class="tree-root"><img :src="avatar(z.wang)"><div><b>{{z.wang}}</b><small>{{z.head}}</small></div></div><div class="root-line"></div><div class="tree-groups"><div v-for="(g,i) in taskGroups" :key="g.id" class="tree-group"><div class="tree-branch"></div><div class="leader-card" :class="'color'+i"><img :src="avatar(g.leader)"><div><b>{{g.name}}</b><small>{{g.leader}} · {{z.leader}}</small></div></div><div class="member-stack"><div v-for="item in g.items" :key="item.name" class="task-member"><img :src="avatar(item.name)"><div><b>{{item.name}}</b><small>{{item.task}}</small><p><span v-for="state in item.states" :key="state" :class="state">{{stateText(state)}}</span></p></div></div></div></div></div></section>
